//! Task 1.13: exhaustive (event x state) coverage.
//!
//! Every event kind has a row of exactly 9 expectations, one per state. The
//! build breaks (it does not just fail a test) when:
//! - an `Event` variant is added without a matching `EventKind` (`kind_of`),
//! - an `EventKind` is added without a sample (`sample`), a fixture or a row,
//! - a `Phase` is added (the rows are `[Expect; 9]`, `Phase::index` is
//!   exhaustive).
//!
//! `EventKind::ALL` is generated by the same macro that declares the enum, so
//! a new kind cannot be forgotten in the iteration either.

use super::tests::{
    CHIME_ID, CONFIRM_ID, COUNTDOWN_ID, LISTEN_ID, REQ_ID, SPEAK_ID, assert_invariants,
    countdown_unarmed, fire, no_voice, running, slot, speaking, state_in,
};
use super::*;

macro_rules! kinds {
    ($($name:ident),+ $(,)?) => {
        #[derive(Debug, Clone, Copy, PartialEq, Eq)]
        enum EventKind { $($name),+ }
        impl EventKind {
            const ALL: &'static [EventKind] = &[$(EventKind::$name),+];
        }
    };
}

kinds!(
    Wake,
    Shortcut,
    SpeechStart,
    Transcript,
    NoSpeech,
    EmptyTranscript,
    TextSubmitted,
    ReminderDue,
    ToolCalls,
    ToolsDone,
    Reply,
    Failure,
    FailureText,
    AskFollowUp,
    Accept,
    Reject,
    SpeakStarted,
    SpeakDone,
    TtsFailed,
    Watchdog,
    VoiceDown,
    VoiceUp,
    SidecarError,
    Dismiss,
    ChimeDone,
    CountdownReady,
    CountdownCancel,
    CountdownFault,
);

/// Exhaustive on purpose: a new `Event` variant does not compile until it is
/// given a kind (and therefore a row).
fn kind_of(event: &Event) -> EventKind {
    match event {
        Event::Wake => EventKind::Wake,
        Event::Shortcut => EventKind::Shortcut,
        Event::SpeechStart { .. } => EventKind::SpeechStart,
        Event::Transcript { .. } => EventKind::Transcript,
        Event::NoSpeech { .. } => EventKind::NoSpeech,
        Event::EmptyTranscript { .. } => EventKind::EmptyTranscript,
        Event::TextSubmitted { .. } => EventKind::TextSubmitted,
        Event::ReminderDue { .. } => EventKind::ReminderDue,
        Event::ToolCalls { .. } => EventKind::ToolCalls,
        Event::ToolsDone { .. } => EventKind::ToolsDone,
        Event::Reply { .. } => EventKind::Reply,
        Event::Failure { .. } => EventKind::Failure,
        Event::FailureText { .. } => EventKind::FailureText,
        Event::AskFollowUp { .. } => EventKind::AskFollowUp,
        Event::Accept { .. } => EventKind::Accept,
        Event::Reject { .. } => EventKind::Reject,
        Event::SpeakStarted { .. } => EventKind::SpeakStarted,
        Event::SpeakDone { .. } => EventKind::SpeakDone,
        Event::TtsFailed { .. } => EventKind::TtsFailed,
        Event::Watchdog { .. } => EventKind::Watchdog,
        Event::VoiceReadinessChanged { ready: false } => EventKind::VoiceDown,
        Event::VoiceReadinessChanged { ready: true } => EventKind::VoiceUp,
        Event::SidecarError { .. } => EventKind::SidecarError,
        Event::Dismiss => EventKind::Dismiss,
        Event::ChimeDone { .. } => EventKind::ChimeDone,
        Event::CountdownReady { .. } => EventKind::CountdownReady,
        Event::CountdownCancel { .. } => EventKind::CountdownCancel,
        Event::CountdownFault { .. } => EventKind::CountdownFault,
    }
}

macro_rules! effect_kinds {
    ($($name:ident),+ $(,)?) => {
        #[derive(Debug, Clone, Copy, PartialEq, Eq)]
        enum E { $($name),+ }
    };
}

effect_kinds!(
    Speak,
    StopSpeaking,
    Listen,
    CancelListen,
    ForceEndOfSpeech,
    StartRequest,
    RunTool,
    CancelRequest,
    StartTimer,
    CancelTimer,
    ShowIsland,
    HideIsland,
    Chime,
    EnqueueReminder,
    DrainReminders,
    WatchInput,
    StopWatchingInput,
    FinishCountdown,
);

fn effect_kind(effect: &Effect) -> E {
    match effect {
        Effect::Speak { .. } => E::Speak,
        Effect::StopSpeaking => E::StopSpeaking,
        Effect::Listen { .. } => E::Listen,
        Effect::CancelListen { .. } => E::CancelListen,
        Effect::ForceEndOfSpeech { .. } => E::ForceEndOfSpeech,
        Effect::StartRequest { .. } => E::StartRequest,
        Effect::RunTool { .. } => E::RunTool,
        Effect::CancelRequest { .. } => E::CancelRequest,
        Effect::StartTimer { .. } => E::StartTimer,
        Effect::CancelTimer { .. } => E::CancelTimer,
        Effect::ShowIsland => E::ShowIsland,
        Effect::HideIsland => E::HideIsland,
        Effect::Chime { .. } => E::Chime,
        Effect::EnqueueReminder { .. } => E::EnqueueReminder,
        Effect::DrainReminders => E::DrainReminders,
        Effect::WatchInput { .. } => E::WatchInput,
        Effect::StopWatchingInput => E::StopWatchingInput,
        Effect::FinishCountdown { .. } => E::FinishCountdown,
    }
}

/// What a cell of the matrix must do, with voice ready unless the row says so.
#[derive(Debug, Clone, Copy)]
enum Expect {
    /// "-": the event is dropped (same state, no effects).
    Ignored,
    /// Same state, but something happens (effects and/or bookkeeping).
    Stays(&'static [E]),
    /// Moves to another state with exactly these effects, in order.
    Goes(Phase, &'static [E]),
}

use Expect::{Goes, Ignored as I, Stays};

/// One row of the matrix. Column order is `Phase::ALL`:
/// idle, listening, thinking, acting, confirmation, success, error, alert,
/// countdown.
/// Exhaustive on `EventKind`: a new kind does not compile without a row.
fn row(kind: EventKind) -> [Expect; 9] {
    use Phase::*;
    let listen = &[E::Listen, E::StartTimer];
    let to_idle = &[E::HideIsland, E::DrainReminders];
    let reject = &[E::CancelTimer, E::CancelListen, E::Speak];
    let accept = &[E::CancelTimer, E::CancelListen, E::StartTimer, E::RunTool];
    let fail = &[E::CancelRequest, E::Speak];
    let reply = &[E::CancelTimer, E::Speak];
    let think = &[E::CancelTimer, E::StartRequest, E::StartTimer];
    match kind {
        EventKind::Wake => [
            Goes(Listening, &[E::ShowIsland, E::Listen, E::StartTimer]),
            I,
            I,
            I,
            I,
            Goes(Listening, &[E::CancelTimer, E::Listen, E::StartTimer]),
            Goes(Listening, &[E::CancelTimer, E::Listen, E::StartTimer]),
            Goes(
                Listening,
                &[E::CancelTimer, E::StopSpeaking, E::Listen, E::StartTimer],
            ),
            I,
        ],
        EventKind::Shortcut => [
            Goes(Listening, &[E::ShowIsland, E::Listen, E::StartTimer]),
            Goes(
                Idle,
                &[
                    E::CancelTimer,
                    E::CancelListen,
                    E::HideIsland,
                    E::DrainReminders,
                ],
            ),
            Goes(
                Idle,
                &[
                    E::CancelTimer,
                    E::CancelRequest,
                    E::HideIsland,
                    E::DrainReminders,
                ],
            ),
            Goes(
                Idle,
                &[
                    E::CancelTimer,
                    E::CancelRequest,
                    E::HideIsland,
                    E::DrainReminders,
                ],
            ),
            Goes(Success, reject),
            Goes(Listening, &[E::CancelTimer, E::Listen, E::StartTimer]),
            Goes(Listening, &[E::CancelTimer, E::Listen, E::StartTimer]),
            Goes(
                Listening,
                &[E::CancelTimer, E::StopSpeaking, E::Listen, E::StartTimer],
            ),
            Goes(
                Success,
                &[
                    E::CancelTimer,
                    E::StopWatchingInput,
                    E::CancelRequest,
                    E::Speak,
                ],
            ),
        ],
        EventKind::SpeechStart => [
            I,
            Stays(&[E::CancelTimer, E::StartTimer]),
            I,
            I,
            I,
            I,
            I,
            I,
            I,
        ],
        EventKind::Transcript => [
            I,
            Goes(Thinking, think),
            I,
            I,
            Goes(Acting, accept),
            I,
            I,
            I,
            I,
        ],
        EventKind::NoSpeech => [
            I,
            Goes(Idle, &[E::CancelTimer, E::HideIsland, E::DrainReminders]),
            I,
            I,
            Stays(&[E::Listen]),
            I,
            I,
            I,
            I,
        ],
        EventKind::EmptyTranscript => [
            I,
            Goes(Error, &[E::CancelTimer, E::Speak]),
            I,
            I,
            Stays(&[E::Listen]),
            I,
            I,
            I,
            I,
        ],
        EventKind::TextSubmitted => [
            Goes(Thinking, &[E::ShowIsland, E::StartRequest, E::StartTimer]),
            Goes(
                Thinking,
                &[
                    E::CancelTimer,
                    E::CancelListen,
                    E::StartRequest,
                    E::StartTimer,
                ],
            ),
            I,
            I,
            I,
            Goes(Thinking, think),
            Goes(Thinking, think),
            Goes(
                Thinking,
                &[
                    E::CancelTimer,
                    E::StopSpeaking,
                    E::StartRequest,
                    E::StartTimer,
                ],
            ),
            I,
        ],
        EventKind::ReminderDue => [
            Goes(
                ReminderAlert,
                &[E::ShowIsland, E::Chime, E::Speak, E::StartTimer],
            ),
            Stays(&[E::EnqueueReminder]),
            Stays(&[E::EnqueueReminder]),
            Stays(&[E::EnqueueReminder]),
            Stays(&[E::EnqueueReminder]),
            Stays(&[E::EnqueueReminder]),
            Stays(&[E::EnqueueReminder]),
            Stays(&[]),
            Stays(&[E::EnqueueReminder]),
        ],
        EventKind::ToolCalls => [
            I,
            I,
            Goes(Acting, &[E::CancelTimer, E::StartTimer, E::RunTool]),
            I,
            I,
            I,
            I,
            I,
            I,
        ],
        EventKind::ToolsDone => [I, I, I, Goes(Success, reply), I, I, I, I, I],
        EventKind::Reply => [
            I,
            I,
            Goes(Success, reply),
            Goes(Success, reply),
            I,
            I,
            I,
            I,
            I,
        ],
        EventKind::Failure => [I, I, Goes(Error, reply), Goes(Error, reply), I, I, I, I, I],
        EventKind::FailureText => [I, I, Goes(Error, reply), Goes(Error, reply), I, I, I, I, I],
        EventKind::AskFollowUp => [I, I, Stays(reply), I, I, I, I, I, I],
        EventKind::Accept => [I, I, I, I, Goes(Acting, accept), I, I, I, I],
        EventKind::Reject => [I, I, I, I, Goes(Success, reject), I, I, I, I],
        // A state-only update: the matching speech becomes audible (the view's
        // `speaking`). Phases that never speak hold a stale id, so they ignore it.
        EventKind::SpeakStarted => [
            I,
            I,
            Stays(&[]),
            I,
            Stays(&[]),
            Stays(&[]),
            Stays(&[]),
            Stays(&[]),
            Stays(&[]),
        ],
        EventKind::SpeakDone | EventKind::TtsFailed => [
            I,
            I,
            Goes(Listening, listen),
            I,
            Stays(&[E::StartTimer, E::Listen]),
            Stays(&[E::StartTimer]),
            Stays(&[E::StartTimer]),
            // The alert is over once it was heard: it settles like a result.
            Goes(Success, &[E::StopSpeaking, E::StartTimer]),
            Stays(&[]),
        ],
        EventKind::Watchdog => [
            I,
            Goes(Idle, &[E::CancelListen, E::HideIsland, E::DrainReminders]),
            Goes(Error, fail),
            Goes(Error, fail),
            Goes(Success, &[E::CancelListen, E::Speak]),
            Goes(Idle, to_idle),
            Goes(Idle, to_idle),
            Goes(Idle, &[E::StopSpeaking, E::HideIsland, E::DrainReminders]),
            Goes(
                Acting,
                &[E::StopWatchingInput, E::StartTimer, E::FinishCountdown],
            ),
        ],
        EventKind::VoiceDown => [
            Stays(&[]),
            Goes(Error, &[E::CancelTimer, E::CancelListen, E::Speak]),
            Stays(&[]),
            Stays(&[]),
            Stays(&[]),
            Goes(Idle, &[E::CancelTimer, E::HideIsland, E::DrainReminders]),
            Goes(Idle, &[E::CancelTimer, E::HideIsland, E::DrainReminders]),
            Stays(&[]),
            Stays(&[]),
        ],
        EventKind::VoiceUp => [Stays(&[]); 9],
        // Voice goes down in every cell. Only a listen ends its turn; the
        // confirmation and the countdown keep running, and the rest is left alone.
        EventKind::SidecarError => [
            Stays(&[]),
            Goes(Error, &[E::CancelTimer, E::CancelListen, E::Speak]),
            Stays(&[]),
            Stays(&[]),
            Stays(&[]),
            Stays(&[]),
            Stays(&[]),
            Stays(&[]),
            Stays(&[]),
        ],
        EventKind::ChimeDone => [
            I,
            I,
            I,
            I,
            I,
            I,
            I,
            Goes(
                Idle,
                &[
                    E::CancelTimer,
                    E::StopSpeaking,
                    E::HideIsland,
                    E::DrainReminders,
                ],
            ),
            I,
        ],
        EventKind::CountdownReady => [
            I,
            I,
            I,
            I,
            I,
            I,
            I,
            I,
            Stays(&[E::CancelTimer, E::StartTimer, E::Speak]),
        ],
        EventKind::CountdownCancel => [
            I,
            I,
            I,
            I,
            I,
            I,
            I,
            I,
            Goes(
                Success,
                &[
                    E::CancelTimer,
                    E::StopWatchingInput,
                    E::CancelRequest,
                    E::Speak,
                ],
            ),
        ],
        EventKind::CountdownFault => [
            I,
            I,
            I,
            I,
            I,
            I,
            I,
            I,
            Goes(
                Error,
                &[
                    E::CancelTimer,
                    E::StopWatchingInput,
                    E::CancelRequest,
                    E::Speak,
                ],
            ),
        ],
        EventKind::Dismiss => [
            I,
            I,
            I,
            I,
            I,
            I,
            I,
            Goes(
                Idle,
                &[
                    E::CancelTimer,
                    E::StopSpeaking,
                    E::HideIsland,
                    E::DrainReminders,
                ],
            ),
            I,
        ],
    }
}

/// Canonical state for a cell. Speech events need the state that is speaking.
fn fixture(kind: EventKind, phase: Phase) -> State {
    match kind {
        EventKind::VoiceUp => no_voice(state_in(phase)),
        EventKind::SpeakDone | EventKind::TtsFailed | EventKind::SpeakStarted => match phase {
            Phase::Success | Phase::Error => speaking(state_in(phase), SPEAK_ID, ReplyKind::Final),
            Phase::ConfirmationNeeded => {
                let mut s = speaking(state_in(phase), SPEAK_ID, ReplyKind::ConfirmPrompt);
                s.listen_id = None;
                s
            }
            Phase::Thinking => {
                let mut s = speaking(state_in(phase), SPEAK_ID, ReplyKind::AskFollowUp);
                s.request_id = None;
                s.pending = Some(slot());
                s
            }
            Phase::ReminderAlert => speaking(state_in(phase), SPEAK_ID, ReplyKind::Alert),
            Phase::Countdown => {
                let mut s = speaking(state_in(phase), SPEAK_ID, ReplyKind::Countdown);
                s.timers = running(&[TimerKind::Countdown]);
                s
            }
            // These states never speak: the id below is stale there.
            Phase::Idle | Phase::Listening | Phase::Acting => state_in(phase),
        },
        // The host has not said it is watching yet: no deadline, only the guard.
        EventKind::CountdownReady if phase == Phase::Countdown => countdown_unarmed(),
        _ => state_in(phase),
    }
}

/// The event used for a cell, built so its ids match the fixture.
fn sample(kind: EventKind, state: &State) -> Event {
    let listen = state.listen_id.unwrap_or(LISTEN_ID);
    let req = REQ_ID;
    match kind {
        EventKind::Wake => Event::Wake,
        EventKind::Shortcut => Event::Shortcut,
        EventKind::SpeechStart => Event::SpeechStart { id: listen },
        EventKind::Transcript => Event::Transcript {
            id: listen,
            text: "yes".into(),
            lang: None,
        },
        EventKind::NoSpeech => Event::NoSpeech { id: listen },
        EventKind::EmptyTranscript => Event::EmptyTranscript { id: listen },
        EventKind::TextSubmitted => Event::TextSubmitted { text: "hi".into() },
        EventKind::ReminderDue => Event::ReminderDue {
            count: 1,
            silent: false,
        },
        EventKind::ToolCalls => Event::ToolCalls {
            req,
            verdict: ToolVerdict::RunSafe,
        },
        EventKind::ToolsDone => Event::ToolsDone {
            req,
            outcome: ToolsOutcome::Completed,
        },
        EventKind::Reply => Event::Reply {
            req,
            text: "ok".into(),
        },
        EventKind::Failure => Event::Failure { req },
        EventKind::FailureText => Event::FailureText {
            req,
            text: "no such app".into(),
        },
        EventKind::AskFollowUp => Event::AskFollowUp {
            req,
            question: "when?".into(),
            slot: slot(),
        },
        EventKind::Accept => Event::Accept {
            id: state.confirm_id.unwrap_or(CONFIRM_ID),
        },
        EventKind::Reject => Event::Reject {
            id: state.confirm_id.unwrap_or(CONFIRM_ID),
        },
        EventKind::SpeakStarted => Event::SpeakStarted { id: SPEAK_ID },
        EventKind::SpeakDone => Event::SpeakDone { id: SPEAK_ID },
        EventKind::TtsFailed => Event::TtsFailed { id: SPEAK_ID },
        EventKind::Watchdog => fire(state, primary_timer(state.phase)),
        EventKind::VoiceDown => Event::VoiceReadinessChanged { ready: false },
        EventKind::VoiceUp => Event::VoiceReadinessChanged { ready: true },
        EventKind::SidecarError => Event::SidecarError {
            code: SidecarErrorCode::CudaOom,
            id: None,
        },
        EventKind::Dismiss => Event::Dismiss,
        EventKind::ChimeDone => Event::ChimeDone { id: CHIME_ID },
        EventKind::CountdownReady => Event::CountdownReady {
            id: state.countdown_id.unwrap_or(COUNTDOWN_ID),
        },
        EventKind::CountdownCancel => Event::CountdownCancel {
            id: state.countdown_id.unwrap_or(COUNTDOWN_ID),
        },
        EventKind::CountdownFault => Event::CountdownFault {
            id: state.countdown_id.unwrap_or(COUNTDOWN_ID),
        },
    }
}

/// The timer each state is waiting on in its canonical fixture.
fn primary_timer(phase: Phase) -> TimerKind {
    match phase {
        Phase::Idle | Phase::Success | Phase::Error => TimerKind::Settle,
        Phase::Listening => TimerKind::NoSpeech,
        Phase::Thinking => TimerKind::Llm,
        Phase::Acting => TimerKind::Tool,
        Phase::ConfirmationNeeded => TimerKind::Confirm,
        Phase::ReminderAlert => TimerKind::AlertEnd,
        Phase::Countdown => TimerKind::Countdown,
    }
}

#[test]
fn every_event_kind_has_a_sample_that_maps_back_to_it() {
    for &kind in EventKind::ALL {
        for phase in Phase::ALL {
            let state = fixture(kind, phase);
            assert_eq!(
                kind_of(&sample(kind, &state)),
                kind,
                "{kind:?} in {phase:?}"
            );
        }
    }
}

#[test]
fn rows_follow_the_phase_order_and_fixtures_are_consistent() {
    for phase in Phase::ALL {
        assert_eq!(state_in(phase).phase, phase);
        assert_invariants(&state_in(phase), "fixture");
    }
}

/// Task 3.2: voice comes back through `VoiceReadinessChanged{ready:true}` and
/// nothing else, in any state.
#[test]
fn only_voice_up_turns_voice_back_on() {
    for &kind in EventKind::ALL {
        for phase in Phase::ALL {
            let start = no_voice(fixture(kind, phase));
            let event = sample(kind, &start);
            let (after, _) = reduce(start, event);
            assert_eq!(
                after.voice_available,
                kind == EventKind::VoiceUp,
                "{kind:?} in {phase:?}"
            );
        }
    }
}

#[test]
fn every_event_x_state_cell_is_asserted() {
    let mut checked = 0;
    for &kind in EventKind::ALL {
        let expectations = row(kind);
        for phase in Phase::ALL {
            let expect = expectations[phase.index()];
            let start = fixture(kind, phase);
            let event = sample(kind, &start);
            let context = format!("{kind:?} in {phase:?}");

            let (after, fx) = reduce(start.clone(), event);
            let got: Vec<E> = fx.iter().map(effect_kind).collect();
            assert_invariants(&after, &context);
            if kind == EventKind::SidecarError {
                assert!(!after.voice_available, "{context}: voice goes down");
            }
            // The one effect that can end in the OS call exists in one cell only.
            assert_eq!(
                got.contains(&E::FinishCountdown),
                kind == EventKind::Watchdog && phase == Phase::Countdown,
                "{context}: FinishCountdown is emitted by the countdown deadline only"
            );
            // Watching stops whenever the countdown is left, and only then.
            assert_eq!(
                got.contains(&E::StopWatchingInput),
                phase == Phase::Countdown && after.phase != Phase::Countdown,
                "{context}: StopWatchingInput on every exit from the countdown"
            );

            match expect {
                Expect::Ignored => {
                    assert_eq!(after, start, "{context}: must be ignored");
                    assert!(fx.is_empty(), "{context}: must emit nothing: {fx:?}");
                }
                Expect::Stays(want) => {
                    assert_eq!(after.phase, phase, "{context}: must stay");
                    assert_eq!(got, want, "{context}: effects {fx:?}");
                    assert!(
                        after != start || !fx.is_empty(),
                        "{context}: a Stays cell must do something (else it is Ignored)"
                    );
                }
                Expect::Goes(to, want) => {
                    assert_eq!(after.phase, to, "{context}: target state");
                    assert_eq!(got, want, "{context}: effects {fx:?}");
                }
            }
            checked += 1;
        }
    }
    assert_eq!(checked, EventKind::ALL.len() * Phase::ALL.len());
}

/// `SpeakStarted` never emits an effect or changes the phase: it only records
/// that the matching speech is audible.
#[test]
fn coverage_matrix_speak_started_is_state_only() {
    for phase in Phase::ALL {
        let start = fixture(EventKind::SpeakStarted, phase);
        let (after, fx) = reduce(start.clone(), sample(EventKind::SpeakStarted, &start));
        assert!(fx.is_empty(), "{phase:?}: {fx:?}");
        assert_eq!(after.phase, phase);
        let speaks = start.speak_id == Some(SPEAK_ID);
        assert_eq!(after.audible_speak, speaks.then_some(SPEAK_ID), "{phase:?}");
    }
}
